     1	// Behaviour shared by every page: the mobile menu, the order dialog, the forms.
     2	(function () {
     3	  'use strict';
     4	
     5	  // Mobile menu
     6	  var toggle = document.querySelector('.nav-toggle');
     7	  var nav = document.getElementById('site-nav');
     8	  if (toggle && nav) {
     9	    toggle.addEventListener('click', function () {
    10	      var open = nav.classList.toggle('is-open');
    11	      toggle.setAttribute('aria-expanded', String(open));
    12	    });
    13	  }
    14	
    15	  // Order dialog
    16	  var modal = document.getElementById('order-modal');
    17	  if (modal) {
    18	    var fill = function (name, value) {
    19	      modal.querySelector('[data-field="' + name + '"]').textContent = value;
    20	    };
    21	    var close = function () {
    22	      modal.hidden = true;
    23	    };
    24	    document.querySelectorAll('[data-order]').forEach(function (button) {
    25	      button.addEventListener('click', function () {
    26	        var row = button.closest('tr');
    27	        fill('id', button.getAttribute('data-order'));
    28	        ['date', 'customer', 'status', 'total'].forEach(function (name) {
    29	          fill(name, row.querySelector('[data-col="' + name + '"]').textContent.trim());
    30	        });
    31	        modal.hidden = false;
    32	        modal.querySelector('.modal-close').focus();
    33	      });
    34	    });
    35	    modal.querySelectorAll('[data-modal-close]').forEach(function (button) {
    36	      button.addEventListener('click', close);
    37	    });
    38	    modal.addEventListener('click', function (event) {
    39	      if (event.target === modal) close();
    40	    });
    41	    document.addEventListener('keydown', function (event) {
    42	      if (event.key === 'Escape') close();
    43	    });
    44	  }
    45	
    46	  // Forms
    47	  var EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    48	  var rules = {
    49	    name: function (v) { return v.trim() ? '' : 'Please enter your name.'; },
    50	    email: function (v) { return EMAIL.test(v.trim()) ? '' : 'Please enter a valid email address.'; },
    51	    message: function (v) { return v.trim().length >= 10 ? '' : 'Please write at least 10 characters.'; },
    52	    consent: function (v, field) { return field.checked ? '' : 'Please agree before sending.'; }
    53	  };
    54	
    55	  function validate(form) {
    56	    var valid = true;
    57	    form.querySelectorAll('[data-validate]').forEach(function (field) {
    58	      var message = rules[field.getAttribute('data-validate')](field.value, field);
    59	      var error = form.querySelector('[data-error-for="' + field.name + '"]');
    60	      field.classList.toggle('is-invalid', Boolean(message));
    61	      if (error) {
    62	        error.textContent = message;
    63	        error.hidden = !message;
    64	      }
    65	      if (message) valid = false;
    66	    });
    67	    return valid;
    68	  }
    69	
    70	  var contact = document.getElementById('contact-form');
    71	  if (contact) {
    72	    contact.addEventListener('submit', function (event) {
    73	      event.preventDefault();
    74	      if (!validate(contact)) return;
    75	      var done = document.getElementById('contact-done');
    76	      done.textContent = 'Thanks, ' + contact.elements.name.value.trim() + '. We will reply within one business day.';
    77	      done.hidden = false;
    78	      contact.hidden = true;
    79	    });
    80	  }
    81	
    82	  var newsletter = document.getElementById('newsletter-form');
    83	  if (newsletter) {
    84	    newsletter.addEventListener('submit', function (event) {
    85	      event.preventDefault();
    86	      var note = document.getElementById('newsletter-note');
    87	      if (!validate(newsletter)) {
    88	        note.textContent = 'Please enter a valid email address.';
    89	        return;
    90	      }
    91	      note.textContent = 'You are on the list. Look out for the next issue.';
    92	      newsletter.reset();
    93	    });
    94	  }
    95	})();
